import{_ as i,o as r,c as o,aw as t}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Dynamic Programming (Динамическое программирование)","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/algoritms/paradigms/dynamic-programming.md","filePath":"wiki/dev-commit/theory/algoritms/paradigms/dynamic-programming.md"}'),e={name:"wiki/dev-commit/theory/algoritms/paradigms/dynamic-programming.md"};function l(m,a,n,d,s,c){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="dynamic-programming-динамическое-программирование" tabindex="-1">Dynamic Programming (Динамическое программирование) <a class="header-anchor" href="#dynamic-programming-динамическое-программирование" aria-label="Permalink to &quot;Dynamic Programming (Динамическое программирование)&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><ul><li>Разделение задачи на подзадачи, но подзадачи должны пересекаться: у разных подзадач может быть одна и та же под-под-задача и вместо того чтобы вычислять ее много раз, ее можно вычислить 1 раз, положить в кэш и использовать в дальнейшем</li><li>Похож на &quot;Резделяй и властвуй&quot;</li></ul><h2 id="подходы" tabindex="-1">Подходы <a class="header-anchor" href="#подходы" aria-label="Permalink to &quot;Подходы&quot;">​</a></h2><p><strong>1. Сверху вниз / Мемоизация (Top-down / Memoization)</strong></p><ul><li>Каждый раз, когда требуется выполнить подзадачу, которую мы еще не решили - мы решаем ее и записываем ответ в таблицу, которую потом будем переиспользовать</li><li>[+] Не нужно заранее знать порядок заполнения таблицы</li><li>[+] Таблицу не обязательно заполнять целиком - в ней будет минимальное, необходимое для решения задачи</li></ul><p><strong>2. Снизу вверх / Табуляция (Bottom-up / Tabulation)</strong></p><ul><li>Необходимо заранее определить порядок заполнения таблицы и заполнить ее целиком</li><li>Решение основной задачи заключается в чтении конкретной ячейки таблицы</li></ul><h2 id="использование" tabindex="-1">Использование <a class="header-anchor" href="#использование" aria-label="Permalink to &quot;Использование&quot;">​</a></h2><ul><li>Сравнение данных, н-р исходников программ для определения наболее длинных общих последовательностей текст</li><li>Алгоритмы на графах, н-р поиск кратчайшего расстояния</li><li>Машинной обучение, н-р нейронные сети</li></ul>',10)])])}const p=i(e,[["render",l]]);export{h as __pageData,p as default};
